param([Parameter(ValueFromRemainingArguments=$true)][string[]]$TrialArguments)
$ErrorActionPreference = 'Stop'
$container = (docker inspect caliburn-q019-postgres | ConvertFrom-Json)[0]
if ($LASTEXITCODE -ne 0 -or $container.State.Status -ne 'running') { throw 'Dedicated test database is not running' }
$settings = @{}
foreach ($entry in $container.Config.Env) {
    $pair = $entry.Split('=', 2)
    $settings[$pair[0]] = $pair[1]
}
if ($settings.POSTGRES_DB -ne 'q019_agent_test' -or $settings.POSTGRES_USER -ne 'q019') { throw 'Unexpected test database identity' }
$port = $container.NetworkSettings.Ports.'5432/tcp'[0].HostPort
if ($port -ne '55433') { throw 'Unexpected test database port' }
$env:Q019_TEST_DATABASE_URL = 'postgresql://q019:' + [uri]::EscapeDataString($settings.POSTGRES_PASSWORD) + '@127.0.0.1:55433/q019_agent_test'
$env:PYTHONUTF8 = '1'
$env:PYTHONPATH = 'src'
try {
    & .venv/Scripts/python.exe .test-tmp/ct14_trial.py @TrialArguments
    $trialExit = $LASTEXITCODE
} finally {
    Remove-Item Env:Q019_TEST_DATABASE_URL -ErrorAction SilentlyContinue
    $settings.Clear()
    $container = $null
}
exit $trialExit
